import{_ as e,o as i,c as a,a5 as n}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"Identification","description":"","frontmatter":{"title":"Identification"},"headers":[],"relativePath":"identification/intro.md","filePath":"identification/intro.md","lastUpdated":1789155237000}'),o={name:"identification/intro.md"};function s(r,t,c,d,l,h){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="identification" tabindex="-1">Identification <a class="header-anchor" href="#identification" aria-label="Permalink to &quot;Identification&quot;">​</a></h1><p>Identification measures physical and optical properties to separate natural gems, synthetics, and imitations. This module covers three foundational test groups — physical tests (RI / SG / hardness / cleavage), optical tests (birefringence / pleochroism / UV fluorescence), and distinguishing synthetics and imitations, with same-colour comparison as an applied case.</p><h2 id="identification-topics" tabindex="-1">Identification Topics <a class="header-anchor" href="#identification-topics" aria-label="Permalink to &quot;Identification Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./identification-workflow.html">Identification Workflow &amp; Documentation</a></td><td>Professional identification is not a search for one “magic reading”; it is a reproducible chain of evidence. Record the sample first, begin with low-risk observations, combine physical, optical, and inclusion clues, then state the confidence limits, treatment disclosure, and whether a laboratory report is needed.</td></tr><tr><td><a href="./physical-tests.html">Physical Tests</a></td><td>Refractive index, specific gravity, hardness, and cleavage are the most basic identification tools — influenced by chemistry and crystal structure, so each species tends to fall within a comparable range; conditions, orientation, treatment, and sample state can shift the reading.</td></tr><tr><td><a href="./optical-tests.html">Optical Tests</a></td><td>Birefringence (polariscope), pleochroism (dichroscope), and UV fluorescence (UV lamp) provide optical and material clues — useful for screening species and deciding what to test next.</td></tr><tr><td><a href="./synthetic-and-imitation.html">Synthetics &amp; Imitations</a></td><td>Synthetics (same chemistry — flux ruby, hydrothermal emerald, CVD diamond) and imitations (different chemistry — glass, cubic zirconia, doublets) demand different identification routes.</td></tr><tr><td><a href="./same-color-gems.html">Same-Colour Gems</a></td><td>One colour can hide many species — red may be ruby, spinel, garnet, or glass. Combining RI / SG / pleochroism / inclusions eliminates candidates one by one. The trees below cover the three most confusing families: red, blue, and green.</td></tr></tbody></table>',4)])])}const p=e(o,[["render",s]]);export{f as __pageData,p as default};
